/** A real process halt after only the pushed destination chunk is durable must recover one block owner. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearPushRecoveryChecks {
    private static final BlockPos ROOT=new BlockPos(12,110,8),SOURCE=ROOT.east(3).above(),TARGET=SOURCE.east();
    private static final AtomicBoolean pause=new AtomicBoolean();private static ServerLevel world;private static Actor actor;private static boolean running,fired;private static int stage,ticks,checks;
    private static String phase(){return System.getProperty("vandorlabs.gearPushRecovery","");}
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211491),"NativePushRecovery"));}}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Push recovery "+phase()+" stage="+stage+" ticks="+ticks+": "+why);}
    private static NativeGearEntity root(){var root=NativeGearFormation.at(world,ROOT);need(root!=null&&!root.inert(),"healthy retained root");return root;}
    private static void click(){actor.setPos(12.5,112,5);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(ROOT).add(0,0,-.5),Direction.NORTH,ROOT,false)).consumesAction(),"actual manual activation");}
    private static CompletableFuture<Void> saveChunk(BlockPos at){var pos=new ChunkPos(at);var chunk=world.getChunkSource().getChunkNow(pos.x,pos.z);need(chunk!=null,"loaded checkpoint target");return world.getChunkSource().chunkMap.write(pos,ChunkSerializer.write(world,chunk)).thenCompose(ignored->((NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true));}
    private static void fault(String where){if(!where.equals("push-after-install")||fired)return;fired=true;pause.set(true);need(world.getBlockState(SOURCE).isAir()&&world.getBlockState(TARGET).is(Blocks.GOLD_BLOCK),"first push owns target in memory");need(root().payload()!=null&&!root().payload().materialized()&&root().progress()>0&&root().progress()<1,"arm remains fractional captured owner");saveChunk(TARGET).thenRun(()->{System.out.println("[vandorlabs][gear-push-recovery] crash PASS checks="+checks+" ARMED/destinationOnlyCrossChunkSave/RuntimeHalt");System.out.flush();Runtime.getRuntime().halt(0);});}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);for(int x=-1;x<=2;x++)for(int z=-1;z<=1;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}if(phase().equals("recover")){need(root().blocked()&&root().settings().pushBlocks()&&root().progress()>0&&root().progress()<1,"fractional push before-image restored before gameplay");need(world.getBlockState(SOURCE).is(Blocks.GOLD_BLOCK)&&world.getBlockState(TARGET).isAir(),"exactly one restored gold owner after target-only save");need(root().payload()!=null&&!root().payload().materialized(),"original payload remains captured");root().authorize(actor);need(root().configure(root().settings(),true),"retry recovered outward target");stage=10;running=true;return;}for(int x=8;x<=20;x++)for(int y=106;y<=116;y++)for(int z=4;z<=12;z++)world.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),18);world.setBlock(ROOT.west(),Blocks.STONE.defaultBlockState(),3);actor.setPos(12.5,112,5);var stack=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.EXTENDER.id),8);var choices=NativeGearSettings.defaults().choices();choices.putBoolean("JoinArms",true);choices.putInt("JoinRange",4);var itemData=new CompoundTag();itemData.put(NativeGearItem.SETTINGS,choices);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(itemData));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);world.setBlock(ROOT.above(2).west(),Blocks.STONE.defaultBlockState(),3);for(int height:new int[]{0,2})for(int n=0;n<4;n++){var support=ROOT.above(height).east(n-1);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(.5,0,0),Direction.EAST,support,false)).consumesAction(),"Survival mounted section "+n);}need(stack.isEmpty(),"eight joined sections consumed");NativeGearJournal.testPause=pause::get;running=true;}catch(Throwable failure){fail(failure);}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<1200,"timeout "+root().error()+" phase="+root().progress());if(stage==0){if(!root().controller()||root().assembly().columnHeight()!=4||root().columns().size()!=2)return;world.setBlock(ROOT.east(4),Blocks.STONE_BRICKS.defaultBlockState(),3);world.setBlock(ROOT.east(4).above(),Blocks.STONE_BRICKS.defaultBlockState(),3);world.setBlock(ROOT.east(4).above(2),Blocks.STONE_BRICKS.defaultBlockState(),3);click();stage=1;return;}if(stage==1){need(!root().blocked(),"initial retract "+root().error());if(root().progress()!=0||NativeGearJournal.busy(root())||root().payload()==null||!root().payload().materialized())return;var settings=root().settings().choices();settings.putBoolean("PushBlocks",true);root().authorize(actor);need(root().configure(NativeGearSettings.readChoices(settings),false),"enable push at materialized endpoint");world.setBlock(SOURCE,Blocks.GOLD_BLOCK.defaultBlockState(),3);world.getServer().saveEverything(true,true,true);NativeGearJournal.testFault=NativeGearPushRecoveryChecks::fault;click();stage=2;return;}if(stage==2){need(!root().blocked(),"push before abrupt halt "+root().error());return;}if(stage==10){need(!root().blocked(),"recovered retry "+root().error());if(root().progress()!=1||NativeGearJournal.busy(root())||root().payload()==null||!root().payload().materialized())return;need(world.getBlockState(ROOT.east(4)).is(Blocks.STONE_BRICKS)&&world.getBlockState(ROOT.east(4).above()).is(Blocks.STONE_BRICKS),"original platform reaches native endpoint");need(world.getBlockState(SOURCE).isAir()&&world.getBlockState(TARGET.east()).is(Blocks.GOLD_BLOCK),"contacted block completes remaining contact once");click();stage=11;return;}if(stage==11){need(!root().blocked(),"recovered reversal "+root().error());if(root().progress()!=0||NativeGearJournal.busy(root())||root().payload()==null||!root().payload().materialized())return;need(world.getBlockState(ROOT.east()).is(Blocks.STONE_BRICKS)&&world.getBlockState(ROOT.east().above()).is(Blocks.STONE_BRICKS),"original payload returns native");int gold=0;for(int x=13;x<=19;x++)if(world.getBlockState(new BlockPos(x,111,8)).is(Blocks.GOLD_BLOCK))gold++;need(gold==1&&world.getBlockState(TARGET.east()).is(Blocks.GOLD_BLOCK),"one usable pushed owner after recovery and reversal");finish();}}catch(Throwable failure){fail(failure);}}
    private static void finish(){running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;System.out.println("[vandorlabs][gear-push-recovery] recover PASS checks="+checks+" fractionalRollback/oneOwner/nativeRetry/reversal");world.getServer().saveEverything(true,true,true);world.getServer().halt(false);}
    private static void fail(Throwable failure){running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;failure.printStackTrace();System.out.println("[vandorlabs][gear-push-recovery] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
